import{_ as n,o as i,c as r,a5 as s}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/admin-management/3-10-3-system-health-monitoring/report3_spec.md","filePath":"feature/admin-management/3-10-3-system-health-monitoring/report3_spec.md"}'),e={name:"feature/admin-management/3-10-3-system-health-monitoring/report3_spec.md"};function h(o,t,g,c,l,a){return i(),r("div",null,[...t[0]||(t[0]=[s("<p><strong>3.10.3 System Health Monitoring (Giám Sát Sức Khỏe Hệ Thống Microservices)</strong></p><p><strong>Function Trigger</strong></p><p>Bắt đầu khi Quản trị viên (ADMIN) truy cập trang giám sát tại /admin/system-health.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: ADMIN. Quản trị viên kỹ thuật giám sát tình trạng hạ tầng microservices.</li><li><strong>Purpose</strong>: Giám sát trạng thái hoạt động (UP, DEGRADED, DOWN), mức sử dụng CPU/RAM và độ trễ phản hồi của 7 microservices trong hệ thống BrandHub.</li><li><strong>Interface</strong>: Màn hình Giám Sát Sức Khỏe Hệ Thống (SCR-ADM-03), gồm lưới trạng thái các service, biểu đồ tài nguyên thời gian thực và nhật ký cảnh báo sự cố.</li><li><strong>Data Processing</strong>: Hệ thống gửi yêu cầu kiểm tra sức khỏe (/actuator/health) đến 7 microservices (BR-65), đo thời gian phản hồi (latency), thu thập mức tải CPU/RAM, xác định trạng thái tổng thể, và kích hoạt cảnh báo nếu service bị lỗi.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Bảng điều khiển Giám Sát Sức Khỏe Hệ Thống (SCR-ADM-03):</p><ul><li>Left/Header: Sidebar điều hướng Admin; Top Header hiển thị tiêu đề &quot;Giám sát Sức khỏe Hệ thống&quot;, nhãn trạng thái chung (&quot;7/7 Dịch vụ Hoạt động tốt&quot;) và nút &quot;Ping kiểm tra toàn bộ&quot;.</li><li>Center: Lưới thẻ 7 microservices (api-gateway, auth-service, business-service, ai-service, publisher-service, notification-service, payment-service): Mỗi thẻ hiển thị Tên service, Badge trạng thái (UP màu xanh, DEGRADED màu vàng, DOWN màu đỏ), Độ trễ phản hồi (ms), % CPU, % RAM, Thời gian hoạt động liên tục (uptime); Khung biểu đồ độ trễ 24 giờ qua; Bảng sự cố gần đây.</li><li>Buttons: Nút &quot;Ping kiểm tra toàn bộ&quot; (màu xanh), Nút &quot;Làm mới&quot;, Bộ lọc trạng thái service (Tất cả, Đang lỗi, Cảnh báo).</li><li>Footer: Dấu thời gian lần kiểm tra gần nhất và chu kỳ tự động làm mới (mặc định mỗi 30 giây).</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: Không có (hệ thống tự động thăm dò định kỳ 30 giây một lần).</li><li><strong>Input optional</strong>: serviceName (lọc theo service cụ thể), refreshInterval (chu kỳ làm mới: 10s, 30s, 60s).</li><li><strong>System data</strong>: servicesList (mảng 7 service), status (UP, DEGRADED, DOWN), latencyMs, cpuUsagePercent, memoryUsagePercent, diskFreeBytes, lastPingTimestamp.</li><li><strong>Output</strong>: Danh sách chi tiết sức khỏe các microservices kèm mã phản hồi HTTP 200 OK.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-65</strong>: Giám sát sức khỏe hệ thống microservices là khu vực kỹ thuật độc quyền của vai trò ADMIN.</li><li><strong>BR-35</strong>: Xác thực quyền hạn ADMIN trước khi tiếp nhận và trả về các chỉ số nhạy cảm của hạ tầng.</li><li><strong>BR-16</strong>: Các sự cố gián đoạn dịch vụ hoặc chuyển trạng thái DOWN/DEGRADED đều được tự động lưu vào nhật ký kiểm toán hệ thống.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Người dùng không có quyền ADMIN -&gt; Display: <strong>MSG39</strong></li><li>Dịch vụ microservice không phản hồi hoặc mất kết nối -&gt; Display: <strong>MSG38</strong></li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>Admin truy cập màn hình Giám sát Sức khỏe (/admin/system-health).</li><li>Hệ thống xác thực quyền ADMIN theo BR-35, BR-65.</li><li>Hệ thống gửi yêu cầu kiểm tra sức khỏe (/actuator/health) tới 7 microservices.</li><li>Hệ thống tiếp nhận phản hồi, tính toán độ trễ, CPU, RAM và xác định trạng thái của từng service.</li><li>Hệ thống hiển thị trạng thái các service lên màn hình SCR-ADM-03 theo dải màu trực quan.</li><li>Cứ sau mỗi 30 giây, hệ thống tự động kiểm tra lại và cập nhật trạng thái mới nhất.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>2.a1: Nếu người dùng không có vai trò ADMIN, hệ thống từ chối truy cập và hiển thị <strong>MSG39</strong>.</li><li>4.a1: Nếu một service không phản hồi sau 3000ms, hệ thống đánh dấu trạng thái DOWN màu đỏ và hiển thị <strong>MSG38</strong>.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>Dữ liệu sức khỏe microservices được cập nhật liên tục trên màn hình giám sát.</li><li>Các sự cố gián đoạn dịch vụ được lưu vào bảng system_health_logs (BR-16).</li></ul>",14)])])}const p=n(e,[["render",h]]);export{m as __pageData,p as default};
